ALLOWED_SORT = {"id": "id", "name": "uname"}


def login(con, uname, pwd):
    # 结构写死, 参数只作为值参与绑定
    return con.execute(
        "SELECT id, role FROM users WHERE uname = ? AND pwd = ?",
        (uname, pwd),
    ).fetchall()


def list_users(con, sort_key):
    # 标识符位置不能用占位符, 必须白名单映射
    col = ALLOWED_SORT.get(sort_key, "id")
    return con.execute("SELECT id, uname FROM users ORDER BY " + col).fetchall()

