import re

GRANTS = [
    ("app", "10.0.0.5", "SELECT", "shop", "orders", 0),
    ("app", "10.0.0.5", "SELECT", "shop", "order_item", 0),
    ("report", "%", "SELECT", "shop", "*", 0),
    ("ops", "10.0.0.%", "ALL", "shop", "*", 1),
    ("readonly", "10.0.0.7", "SELECT", "shop", "*", 0),
]


def _pat(v):
    return re.compile("^" + re.escape(v).replace("%", ".*") + "$")


def decide(user, host, action, db, table):
    for u, h, a, d, t, _ in GRANTS:
        if u != user or d != db:
            continue
        if not _pat(h).match(host):
            continue
        if not (t == "*" or _pat(t).match(table)):
            continue
        if not (a == "ALL" or a == action):
            continue
        return True
    return False    # 默认拒绝

